WITH RECURSIVE x12 AS (SELECT 1, CONCAT(SHA2(RAND(), 0), SHA2(RAND(), 0)) UNION ALL SELECT x7.v137928 + 1, CONCAT(SHA2(RAND(), 0), SHA2(RAND(), 0)) FROM x13 WHERE x7.v137928 < 10000) SELECT x7.v137928, x7.v137928, CONCAT_WS('<------------------>', x7.v137928, x7.v137928) AS x4, x7.v137928 FROM v137927 AS x7 WHERE x7.v137928 <= 4